export const VIBE_ROTACION_ICON: Record<VibeRotacion, string> = { yocpmd: '⚙️', preguntas: '❓', bots: '🤖', contenido: '🎬' };

export function vibeDiaDe(fechaISO: string): DiaVibe | undefined { return VIBE_DIAS.find((x) => x.fecha === fechaISO); }
export function vibeProyectoDe(s: number): VibeProyecto | undefined { return VIBE_PROYECTOS.find((x) => x.s === s); }
export function vibeTaperDe(s: number): VibeTaper | undefined { return VIBE_TAPER.find((x) => x.s === s); }
/** v6.01 (10-oct-2026): bloque(s) PC del SYNAPSE de un sábado, con el MISMO orden y la MISMA regla que gen_synapse_plan.js
 *  (PC_DESPLAZADOS + bloquePC): 1.º las entradas del taper cuyo PC propio se desplazó a ese sábado (S16 → sáb 27-feb en v6.06 · S16 → sáb 20-feb en v6.05 · ninguna en v6.03 · S16 → sáb 13-feb en v6.02 —sáb 6-feb en v6.01—, porque
 *  S15 y S16 cierran la misma semana), luego la entrada que hace SHIP ese sábado (proyecto → 'ship' · taper → 'taper') y, si ninguna cierra
 *  ese sábado, la que está en curso (proyecto → 'avance': aún no terminó; v6.06: sáb 26-dic = avance de S8, que termina el lun 28-dic y hace SHIP el sáb 2-ene · v6.05: sáb 26-dic = avance de S9, que termina el lun 28-dic y hace SHIP el sáb 2-ene · v6.03: sáb 24-oct = avance de S1, que termina el mar 27-oct y hace SHIP el sáb 31-oct · sáb 26-dic = avance de S10 en v6.02 —S11 en v6.01—, que termina el lun 28-dic y hace SHIP
 *  el sáb 2-ene). El ÚLTIMO elemento es el principal (cabecera de la card). [] si no es sábado o cae fuera del plan.
 *  v6.06: igual (S16 ship = pcSab = sáb 27-feb). v6.05 (fix 24-oct): la regla lee SOLO pcSab (= ship desde el fix: S16 ship = pcSab = sáb 20-feb) → el sábado lleva todas las entradas con
 *  pcSab = ese sábado, en orden de S (las desplazadas antes que la que cierra); pcSab '' = SIN PC (S20: su sábado, 13-mar, es PROTEGIDO) y
 *  tampoco cuenta como «en curso». */
/** v6.06 (31-oct-2026): días PROTEGIDOS de _fechas_v6.json — sin PC (vibePCDomingo) aunque haya una entrada en curso. */
const VIBE_PROTEGIDOS = new Set<string>(["2027-03-12","2027-03-13","2027-03-14","2027-03-15","2027-12-18","2027-12-19","2027-12-20"]);
/** v6.09 (16-nov-2026): días SIN SESIÓN de _fechas_v6.json › corrida_s1 dentro del plan (dom 22-nov, viaje) — sin PC aunque haya una entrada en curso
 *  (el SHIP S1 es el dom 29-nov). */
const VIBE_SIN_SESION = new Set<string>([]);
/** v6.07 (8-nov-2026): el PC del SYNAPSE (SHIP · avance · taper) es el DOMINGO (flexible, 2 h); [] en cualquier otro día. Misma regla que antes en sábado. */
export function vibePCDomingo(fechaISO: string): VibePCSabado[] {
  // v6.06 (31-oct-2026): un día PROTEGIDO no tiene PC (ni la entrada «en curso»; v6.07: el dom 14-mar = ENCAPS)
  if (diaSemanaISO(fechaISO) !== VIBE_META.diaShip || VIBE_PROTEGIDOS.has(fechaISO) || VIBE_SIN_SESION.has(fechaISO)) return []; // v6.09: + sin sesión (dom 22-nov)
  const todos: Array<VibeProyecto | VibeTaper> = [...VIBE_PROYECTOS, ...VIBE_TAPER];
  const delSab = todos.filter((x) => x.pcSab === fechaISO);
  const enCurso = delSab.length ? undefined : todos.find((x) => x.pcSab !== '' && x.ini <= fechaISO && fechaISO <= x.ship);
  return [...delSab, ...(enCurso ? [enCurso] : [])].map((x): VibePCSabado => {
    const tp = vibeTaperDe(x.s);
    return tp ? { tipo: 'taper', s: x.s, taper: tp } : { tipo: delSab.includes(x) ? 'ship' : 'avance', s: x.s, proyecto: vibeProyectoDe(x.s) };
  });
}
/** @deprecated v6.07: nombre histórico (el PC iba el sábado). Desde la v6.07 el PC es el DOMINGO: devuelve lo mismo que vibePCDomingo (pasar el domingo). */
export const vibePCSabado = vibePCDomingo;
/** Entrada del taper vigente para una fecha. v6.01 (10-oct-2026): L-V = la del DÍA (los bloques del taper ya no son lun → vie y las ventanas
 *  ini → ship+1 se solapan: el mié 17-feb es S16, no S15, en v6.06 · el mié 10-feb es S16, no S15, en v6.05 · el jue 11-feb es S17, no S16, en v6.03 · el jue 21-ene es S14, no S13, en v6.02 —jue 14-ene en v6.01—) · sábado = la del PC del SYNAPSE (vibePCSabado; undefined si ese sábado es el SHIP
 *  de un proyecto: S12 el sáb 30-ene en v6.06 · sáb 23-ene en v6.05 · sáb 16-ene en v6.03 y v6.02 —sáb 9-ene en v6.01—) · domingo/feriado = la del último hábil anterior, hasta el domingo tras su SHIP. undefined fuera del taper. */
export function vibeTaperEnFecha(fechaISO: string): VibeTaper | undefined {
  const pc = vibePCDomingo(fechaISO); // v6.07: el PC es el domingo
  if (pc.length) return pc[pc.length - 1].taper;
  const dia = vibeDiaDe(fechaISO);
  if (dia) return vibeTaperDe(dia.semana);
  const prev = [...VIBE_DIAS].reverse().find((x) => x.fecha < fechaISO);
  const t = prev ? vibeTaperDe(prev.semana) : undefined;
  return t && fechaISO <= (VIBE_META.diaShip === 0 ? t.ship : addDiasISO(t.ship, 1)) ? t : undefined; // v6.07: el SHIP ya es el domingo (hasta v6.06: sábado + 1)
}
/** Proyecto vigente para una fecha: el de su semana L-V, o (sáb/dom) el de la semana que acaba de cerrar.
 *  A partir del taper (S13+) devuelve undefined: usar vibeTaperEnFecha.
 *  v6.01 (10-oct-2026): en sábado manda el PC del SYNAPSE (vibePCSabado): el proyecto que hace SHIP o AVANZA ese día (v6.06: sáb 26-dic = AVANCE de S8, sáb 2-ene = SHIP de S8, sáb 30-ene = SHIP de S12 con el taper desde el jue 28-ene · v6.05: sáb 26-dic = AVANCE de S9, sáb 2-ene = SHIP de S9, sáb 23-ene = SHIP de S12 con el taper desde el jue 21-ene · v6.03: sáb 24-oct = AVANCE de S1, sáb 2-ene = SHIP de S10, sáb 16-ene = SHIP de S12 con el taper desde el lun 18-ene · v6.02: sáb 2-ene = SHIP de S10,
 *  sáb 16-ene = SHIP de S12 aunque el taper ya empezó el jue 14-ene · v6.01: sáb 2-ene = S11, sáb 9-ene = SHIP de S12 con el taper desde el jue 7-ene); undefined si ese sábado el PC es del taper. */
export function vibeProyectoEnFecha(fechaISO: string): VibeProyecto | undefined {
  const pc = vibePCDomingo(fechaISO); // v6.07: el PC es el domingo
  if (pc.length) return pc[pc.length - 1].proyecto;
  if (VIBE_TAPER.length && fechaISO >= VIBE_TAPER[0].ini) return undefined;
  const dia = vibeDiaDe(fechaISO);
  if (dia && dia.semana <= 12) return vibeProyectoDe(dia.semana);
  const prev = [...VIBE_DIAS].filter((x) => x.semana <= 12).reverse().find((x) => x.fecha < fechaISO);
  if (prev) return vibeProyectoDe(prev.semana);
  return VIBE_PROYECTOS[0];
}
/** Nº de proyectos con sus 5 días marcados ✓ (PlanKey 'vibecoding') — auto-reporte, NO es 'shipped'. */
export function vibeShipped(done: Set<number>): number {
  return VIBE_PROYECTOS.filter((p) => VIBE_DIAS.filter((x) => x.semana === p.s).every((x) => done.has(x.d))).length;
}
/** Ship log vivo: horneado + localStorage 'jmd-vibe-ship' (lo escribe el one-liner de verify_vibecoding.js). try/catch. */
export function vibeShipLogLeer(): VibeShipEntry[] {
  let extra: VibeShipEntry[] = [];
  try {
    const raw = (globalThis as any).localStorage?.getItem(VIBE_META.shipKey);
    if (raw) { const j = JSON.parse(raw); extra = Array.isArray(j) ? j : j && typeof j === 'object' ? [j] : []; }
  } catch { extra = []; }
  const all = [...VIBE_SHIP_LOG, ...extra].filter((e) => e && typeof e.s === 'number' && typeof e.fecha === 'string');
  const seen = new Set<string>();
  return all.filter((e) => { const k = e.s + '|' + e.fecha + '|' + e.hora; if (seen.has(k)) return false; seen.add(k); return true; })
    .sort((a, b) => (a.fecha + a.hora).localeCompare(b.fecha + b.hora));
}
/** Último verify del proyecto s (undefined si nunca se corrió). */
export function vibeUltimoVerify(s: number, log: VibeShipEntry[] = vibeShipLogLeer()): VibeShipEntry | undefined {
  const xs = log.filter((e) => e.s === s);
  return xs.length ? xs[xs.length - 1] : undefined;
}
/** Nº de proyectos S1-S12 cuyo ÚLTIMO verify dio shipped=true (el KPI real de 'shipped'). */
export function vibeShippedVerificado(log: VibeShipEntry[] = vibeShipLogLeer()): number {
  return VIBE_PROYECTOS.filter((p) => { const u = vibeUltimoVerify(p.s, log); return !!u && u.shipped; }).length;
}
/** Semana ISO (YYYY-Www) de una fecha: nombre del fichero del journal (D:/synapse-journal/journal/<semana>.md). */
export function vibeSemanaISO(fechaISO: string): string {
  try {
    const d = new Date(fechaISO + 'T12:00:00Z');
    const day = (d.getUTCDay() + 6) % 7;
    d.setUTCDate(d.getUTCDate() - day + 3);
    const fy = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
    const w = 1 + Math.round(((d.getTime() - fy.getTime()) / 86400000 - 3 + ((fy.getUTCDay() + 6) % 7)) / 7);
    return d.getUTCFullYear() + '-W' + String(w).padStart(2, '0');
  } catch { return fechaISO.slice(0, 4) + '-W00'; }
}
/** v6.10q (19-nov-2026): semana del journal de un PROYECTO que no va en la de cada fecha (gen_vibecoding_plan.js › JOURNAL_SEM: S1 entero en 2026-W47, kit v5). */
const VIBE_JOURNAL_SEMANA: Record<number, string> = {};
/** v6.10q: semana del journal (fichero <semana>.md) de una fecha del vibecoding — la de PLAN de un día L-V o el domingo del SHIP / Feynman: la de su
 *  proyecto si VIBE_JOURNAL_SEMANA la fija (S1 entero en 2026-W47); si no, su semana ISO (vibeSemanaISO, que sigue siendo la semana ISO pura). */
export function vibeJournalSemanaDe(fechaISO: string): string {
  const pc = vibePCDomingo(fechaISO);
  const s = vibeDiaDe(fechaISO)?.semana ?? (pc.length ? pc[pc.length - 1].s : undefined);
  // v6.10w: la semana ISO del DÍA REAL en que se hace (con la corrida, la fecha de plan del mié 18 se hace el lun 23: S1 entero en 2026-W48)
  return (s !== undefined ? VIBE_JOURNAL_SEMANA[s] : undefined) ?? vibeSemanaISO(fechaRealDe(fechaISO, 'vibecoding'));
}
/** Ruta del journal de la semana y su URL vscode:// (VS Code instalado en el PC de Joseph; en móvil no abre). v6.10q: semana = vibeJournalSemanaDe. */
export function vibeJournalPath(fechaISO: string): string { return VIBE_META.journalRoot + '/journal/' + vibeJournalSemanaDe(fechaISO) + '.md'; }
export function vibeJournalUrl(fechaISO: string): string { return 'vscode://file/' + vibeJournalPath(fechaISO); }
function addDiasISO(fechaISO: string, n: number): string {
  try { const d = new Date(fechaISO + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); } catch { return fechaISO; }
}
/** 0 = domingo … 6 = sábado (UTC a mediodía, igual que addDiasISO); NaN si la fecha no es válida. */
function diaSemanaISO(fechaISO: string): number { return new Date(fechaISO + 'T12:00:00Z').getUTCDay(); }
